-- Real API roles, two owners, real grants and independent RLS checks. Changes roll back.
begin;
create extension if not exists pgtap with schema extensions;
set local search_path = public, extensions;
select no_plan();
insert into public.assets(story_id,kind,storage_path,mime_type) values
 ('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1','hero','11111111-1111-4111-8111-111111111111/aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1/ffffffff-ffff-4fff-8fff-ffffffffffff.png','image/png'),
 ('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb1','hero','22222222-2222-4222-8222-222222222222/bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb1/ffffffff-ffff-4fff-8fff-fffffffffff2.png','image/png');
insert into public.story_pages(story_id,page_number,content) values
 ('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb1',1,'Synthetic page owned by Bob through its parent.');
select is((select count(*) from public.assets),2::bigint,'Nonempty asset fixtures for both owners');
select is((select count(*) from public.story_pages),4::bigint,'Nonempty page fixtures for both owners');
select ok(not has_table_privilege('anon','public.stories','SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER'),'Anonymous has no stories grants');
select ok(not has_table_privilege('authenticated','public.stories','TRUNCATE,REFERENCES,TRIGGER'),'No administrative grants on stories');
select ok(not has_table_privilege('anon','public.story_pages','SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER'),'Anonymous has no story_pages grants');
select ok(not has_table_privilege('authenticated','public.story_pages','TRUNCATE,REFERENCES,TRIGGER'),'No administrative grants on story_pages');
select ok(not has_table_privilege('anon','public.assets','SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER'),'Anonymous has no assets grants');
select ok(not has_table_privilege('authenticated','public.assets','TRUNCATE,REFERENCES,TRIGGER'),'No administrative grants on assets');
select ok(not has_column_privilege('authenticated','public.stories','id','INSERT'),'No INSERT privilege on id');
select ok(not has_column_privilege('authenticated','public.stories','id','UPDATE'),'No UPDATE privilege on id');
select ok(not has_column_privilege('authenticated','public.stories','owner_id','INSERT'),'No INSERT privilege on owner_id');
select ok(not has_column_privilege('authenticated','public.stories','owner_id','UPDATE'),'No UPDATE privilege on owner_id');
select ok(not has_column_privilege('authenticated','public.stories','status','INSERT'),'No INSERT privilege on status');
select ok(not has_column_privilege('authenticated','public.stories','status','UPDATE'),'No UPDATE privilege on status');
select ok(not has_column_privilege('authenticated','public.stories','created_at','INSERT'),'No INSERT privilege on created_at');
select ok(not has_column_privilege('authenticated','public.stories','created_at','UPDATE'),'No UPDATE privilege on created_at');
select ok(not has_column_privilege('authenticated','public.stories','updated_at','INSERT'),'No INSERT privilege on updated_at');
select ok(not has_column_privilege('authenticated','public.stories','updated_at','UPDATE'),'No UPDATE privilege on updated_at');
reset role;
select set_config('request.jwt.claims','{"role": "anon"}',true);
set local role anon;
select throws_ok($$select * from public.stories$$,'42501',null,'Anonymous denied: select stories');
select throws_ok($$delete from public.stories$$,'42501',null,'Anonymous denied: delete stories');
select throws_ok($$update public.stories set id=id$$,'42501',null,'Anonymous denied: update stories');
select throws_ok($$select * from public.story_pages$$,'42501',null,'Anonymous denied: select story_pages');
select throws_ok($$delete from public.story_pages$$,'42501',null,'Anonymous denied: delete story_pages');
select throws_ok($$update public.story_pages set id=id$$,'42501',null,'Anonymous denied: update story_pages');
select throws_ok($$select * from public.assets$$,'42501',null,'Anonymous denied: select assets');
select throws_ok($$delete from public.assets$$,'42501',null,'Anonymous denied: delete assets');
select throws_ok($$update public.assets set id=id$$,'42501',null,'Anonymous denied: update assets');
select throws_ok($$insert into public.stories(title,child_name,prompt) values ('Anonymous','Nova','Map')$$,'42501',null,'Anonymous cannot create stories');
reset role;
select set_config('request.jwt.claims','{"role": "authenticated"}',true);
set local role authenticated;
select is_empty($$select * from public.stories$$,'Missing uid cannot read stories');
select is_empty($$select * from public.story_pages$$,'Missing uid cannot read story_pages');
select is_empty($$select * from public.assets$$,'Missing uid cannot read assets');
select throws_ok($$insert into public.stories(title,child_name,prompt) values ('No identity','Nova','Map')$$,'42501',null,'Missing uid cannot create a story');
select is_empty($$update public.stories set title='No identity' returning id$$,'Missing uid cannot update stories');
select is_empty($$delete from public.stories returning id$$,'Missing uid cannot delete stories');
