select set_config('request.jwt.claims','{"role": "authenticated", "sub": "11111111-1111-4111-8111-111111111111", "user_metadata": {"owner_id": "22222222-2222-4222-8222-222222222222", "role": "admin"}}',true);
set local role authenticated;
select is(auth.uid(),'11111111-1111-4111-8111-111111111111'::uuid,'Alice authenticated identity');
select is((select count(*) from public.stories),2::bigint,'Alice only reads owned stories, even with forged user metadata');
select is((select count(*) from public.story_pages),3::bigint,'Alice only reads owned story_pages, even with forged user metadata');
select is((select count(*) from public.assets),1::bigint,'Alice only reads owned assets, even with forged user metadata');
select is_empty($$select * from public.stories where id='bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb1'$$,'Alice cannot read another story by ID');
select is_empty($$select * from public.story_pages where story_id='bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb1'$$,'Alice cannot read other story_pages by parent ID');
select is_empty($$select * from public.assets where story_id='bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb1'$$,'Alice cannot read other assets by parent ID');
