select is((select owner_id from public.stories where title='Alice created'),'11111111-1111-4111-8111-111111111111'::uuid,'Alice owner default uses JWT identity');
select is((select status from public.stories where title='Alice created'),'draft','Alice story starts in draft');
select lives_ok($$update public.stories set title='Alice edited', child_name='Sol', prompt='New map' where title='Alice created'$$,'Alice updates allowed story columns');
select is((select child_name from public.stories where title='Alice edited'),'Sol','Alice update persists');
select results_eq($$delete from public.stories where title='Alice edited' returning title$$,array['Alice edited'],'Alice deletes own story');
select is_empty($$update public.stories set title='Stolen' where id='bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb1' returning id$$,'Alice cannot update another story');
select is_empty($$delete from public.stories where id='bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb1' returning id$$,'Alice cannot delete another story');
select throws_ok($$update public.stories set id='cccccccc-cccc-4ccc-8ccc-cccccccccccc' where id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1'$$,'42501',null,'Alice cannot overwrite id');
select throws_ok($$insert into public.stories(title,child_name,prompt,id) values ('Forged','Nova','Map','cccccccc-cccc-4ccc-8ccc-cccccccccccc')$$,'42501',null,'Alice cannot supply id on insert');
select throws_ok($$update public.stories set owner_id='22222222-2222-4222-8222-222222222222' where id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1'$$,'42501',null,'Alice cannot overwrite owner_id');
select throws_ok($$insert into public.stories(title,child_name,prompt,owner_id) values ('Forged','Nova','Map','22222222-2222-4222-8222-222222222222')$$,'42501',null,'Alice cannot supply owner_id on insert');
select throws_ok($$update public.stories set status='complete' where id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1'$$,'42501',null,'Alice cannot overwrite status');
