select throws_ok($$update public.stories set updated_at='2000-01-01' where id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1'$$,'42501',null,'Alice cannot overwrite updated_at');
select throws_ok($$insert into public.stories(title,child_name,prompt,updated_at) values ('Forged','Nova','Map','2000-01-01')$$,'42501',null,'Alice cannot supply updated_at on insert');
select throws_ok($$insert into public.story_pages(story_id,page_number,content) values ('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1',10,'Injected')$$,'42501',null,'Alice cannot inject pages into own story');
select throws_ok($$insert into public.assets(story_id,kind,storage_path,mime_type) values ('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1','hero','11111111-1111-4111-8111-111111111111/aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1/ffffffff-ffff-4fff-8fff-fffffffffff3.png','image/png')$$,'23505',null,'Alice cannot reserve a second hero image');
select throws_ok($$update public.story_pages set story_id='bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb1' where story_id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1'$$,'42501',null,'Alice cannot reparent own story_pages');
select throws_ok($$delete from public.story_pages where story_id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1'$$,'42501',null,'Alice cannot directly delete own story_pages');
select throws_ok($$update public.assets set story_id='bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb1' where story_id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1'$$,'42501',null,'Alice cannot reparent own assets');
select throws_ok($$insert into public.story_pages(story_id,page_number,content) values ('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb1',10,'Injected')$$,'42501',null,'Alice cannot inject pages into another story');
select throws_ok($$insert into public.assets(story_id,kind,storage_path,mime_type) values ('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb1','hero','11111111-1111-4111-8111-111111111111/bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb1/ffffffff-ffff-4fff-8fff-fffffffffff3.png','image/png')$$,'42501',null,'Alice cannot inject assets into another story');
select throws_ok($$update public.story_pages set story_id='bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb1' where story_id='bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb1'$$,'42501',null,'Alice cannot reparent another story_pages');
select throws_ok($$delete from public.story_pages where story_id='bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb1'$$,'42501',null,'Alice cannot directly delete another story_pages');
