select is_empty($$delete from public.assets where story_id='bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb1' returning id$$,'Alice cannot directly delete another assets');
select results_eq($$delete from public.stories where id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1' returning id$$,array['aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1'::uuid],'Alice can delete a parent with children');
select is_empty($$select * from public.story_pages where story_id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1'$$,'Alice deleted children disappear');
select is_empty($$select * from public.assets where story_id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1'$$,'Alice deleted children disappear');
reset role;
insert into public.stories(id,owner_id,title,child_name,prompt) values ('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1','11111111-1111-4111-8111-111111111111','Restored Alice','Nova','Map');
