select is((select count(*) from public.story_pages),1::bigint,'Bob only reads owned story_pages, even with forged user metadata');
select is((select count(*) from public.assets),1::bigint,'Bob only reads owned assets, even with forged user metadata');
select is_empty($$select * from public.stories where id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1'$$,'Bob cannot read another story by ID');
select is_empty($$select * from public.story_pages where story_id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1'$$,'Bob cannot read other story_pages by parent ID');
select is_empty($$select * from public.assets where story_id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1'$$,'Bob cannot read other assets by parent ID');
select lives_ok($$insert into public.stories(title,child_name,prompt) values ('Bob created','Nova','A map')$$,'Bob creates an owned story without supplying owner');
select is((select owner_id from public.stories where title='Bob created'),'22222222-2222-4222-8222-222222222222'::uuid,'Bob owner default uses JWT identity');
select is((select status from public.stories where title='Bob created'),'draft','Bob story starts in draft');
select lives_ok($$update public.stories set title='Bob edited', child_name='Sol', prompt='New map' where title='Bob created'$$,'Bob updates allowed story columns');
select is((select child_name from public.stories where title='Bob edited'),'Sol','Bob update persists');
select results_eq($$delete from public.stories where title='Bob edited' returning title$$,array['Bob edited'],'Bob deletes own story');
select is_empty($$update public.stories set title='Stolen' where id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1' returning id$$,'Bob cannot update another story');
select is_empty($$delete from public.stories where id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1' returning id$$,'Bob cannot delete another story');
select throws_ok($$update public.stories set id='cccccccc-cccc-4ccc-8ccc-cccccccccccc' where id='bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb1'$$,'42501',null,'Bob cannot overwrite id');
