select throws_ok($$insert into public.stories(title,child_name,prompt,owner_id) values ('Forged','Nova','Map','11111111-1111-4111-8111-111111111111')$$,'42501',null,'Bob cannot supply owner_id on insert');
select throws_ok($$update public.stories set status='complete' where id='bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb1'$$,'42501',null,'Bob cannot overwrite status');
