select throws_ok($$insert into public.assets(story_id,kind,storage_path,mime_type) values ('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb1','hero','22222222-2222-4222-8222-222222222222/bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb1/ffffffff-ffff-4fff-8fff-fffffffffff3.png','image/png')$$,'23505',null,'Bob cannot reserve a second hero image');
select throws_ok($$update public.story_pages set story_id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1' where story_id='bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb1'$$,'42501',null,'Bob cannot reparent own story_pages');
