-- Separate RLS from SQL privileges: test-only wider grants are rolled back.
grant insert, update on public.stories to authenticated;
grant insert, update, delete on public.story_pages, public.assets to authenticated;
grant select, insert, update, delete on public.stories, public.story_pages, public.assets to anon;
reset role;
select set_config('request.jwt.claims','{"role": "anon", "sub": "11111111-1111-4111-8111-111111111111"}',true);
set local role anon;
select is_empty($$select * from public.stories$$,'RLS rejects anon even with forged sub and temporary SELECT grant: stories');
select is_empty($$select * from public.story_pages$$,'RLS rejects anon even with forged sub and temporary SELECT grant: story_pages');
select is_empty($$select * from public.assets$$,'RLS rejects anon even with forged sub and temporary SELECT grant: assets');
select throws_ok($$insert into public.stories(title,child_name,prompt) values ('Forged anon','Nova','Map')$$,'42501',null,'RLS rejects anon with temporary INSERT grant');
reset role;
select set_config('request.jwt.claims','{"role": "authenticated", "sub": "11111111-1111-4111-8111-111111111111"}',true);
set local role authenticated;
select throws_ok($$insert into public.stories(owner_id,title,child_name,prompt) values ('22222222-2222-4222-8222-222222222222','Forged owner','Nova','Map')$$,'42501',null,'INSERT WITH CHECK rejects another owner independently of grants');
select throws_ok($$insert into public.stories(title,child_name,prompt,status) values ('Forged status','Nova','Map','complete')$$,'42501',null,'INSERT WITH CHECK rejects non-draft initial status');
select throws_ok($$update public.stories set owner_id='22222222-2222-4222-8222-222222222222' where id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1'$$,'42501',null,'UPDATE WITH CHECK independently rejects ownership transfer');
select is_empty($$update public.stories set owner_id='11111111-1111-4111-8111-111111111111' where id='bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb1' returning id$$,'UPDATE USING independently prevents taking ownership');
select is_empty($$update public.story_pages set id=id returning id$$,'No UPDATE policy for story_pages even if grants widen');
select is_empty($$delete from public.story_pages returning id$$,'No DELETE policy for story_pages even if grants widen');
select is_empty($$update public.assets set id=id returning id$$,'No UPDATE policy for assets even if grants widen');
select is_empty($$delete from public.assets where story_id='bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb1' returning id$$,'Asset DELETE policy still excludes other owners when grants widen');
select throws_ok($$insert into public.story_pages(story_id,page_number,content) values ('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb1',10,'Injected')$$,'42501',null,'RLS prevents child injection independently of grants');
select throws_ok($$insert into public.assets(story_id,kind,storage_path,mime_type) values ('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb1','hero','11111111-1111-4111-8111-111111111111/bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb1/ffffffff-ffff-4fff-8fff-fffffffffff4.png','image/png')$$,'42501',null,'RLS prevents asset injection independently of grants');
reset role;
select * from finish();
rollback;
